    var zoneTags = {1:'ZON 1 Aktif', 2:'ZON 2 Aktif', 3:'ZON 3 Aktif'};

    function getDayIndex() {
        var s = new Date(2026,1,19); s.setHours(0,0,0,0);
        var t = new Date(); t.setHours(0,0,0,0);
        return Math.floor((t-s)/86400000);
    }

    function renderTable() {
        var tbody = document.getElementById('ilmxN9TableBody');
        if (!tbody) return;
        var data = n9Data[currentZone];
        var idx = getDayIndex();
        var html = '';
        data.forEach(function(row, i) {
            var isT = (i === idx);
            html += '<tr' + (isT ? ' class="ilmx-n9-today"' : '') + '>';
            html += '<td>' + row.day + (isT ? ' 🌙' : '') + '</td>';
            html += '<td><strong>' + row.r + '</strong></td>';
            html += '<td>' + row.date + ' 2026</td>';
            html += '<td class="ilmx-n9-time-col">' + row.imsak + '</td>';
            html += '<td class="ilmx-n9-time-col">' + row.berbuka + '</td>';
            html += '</tr>';
        });
        tbody.innerHTML = html;
        document.getElementById('ilmxN9TableTitle').textContent = zoneTitles[currentZone].replace('📅 ','');
        var titleEl = document.getElementById('ilmxN9TableTitle');
        if(titleEl) titleEl.innerHTML = zoneTitles[currentZone];
        document.getElementById('ilmxN9ZoneTag').textContent = zoneTags[currentZone];
        document.getElementById('ilmxN9ZoneInfo').innerHTML = zoneDescriptions[currentZone];
    }

    function updateCards() {
        var idx = getDayIndex();
        if (idx >= 0 && idx < 30) {
            var d = n9Data[currentZone][idx];
            document.getElementById('ilmxN9ImsakCard').textContent = d.imsak;
            document.getElementById('ilmxN9BukaCard').textContent = d.berbuka;
        }
    }

    function startCountdown() {
        if (countdownInterval) clearInterval(countdownInterval);
        var idx = getDayIndex();
        var todayEl = document.getElementById('ilmxN9Today');
        if (idx < 0 || idx >= 30) {
            if (todayEl) todayEl.innerHTML = '<strong>⭐ Ramadan 2026 dijangka bermula 19 Februari 2026 (Khamis)</strong>';
            return;
        }
        var d = n9Data[currentZone][idx];
        var bp = d.berbuka.split(':');
        var n = new Date();
        var target = new Date(n.getFullYear(),n.getMonth(),n.getDate(),parseInt(bp[0]),parseInt(bp[1]),0);
        if (todayEl) todayEl.innerHTML = '<strong>Hari ini (' + d.r + ' Ramadan ' + d.date + '):</strong> Imsak ' + d.imsak + ' | Berbuka ' + d.berbuka;
        countdownInterval = setInterval(function() {
            var now = new Date(); var diff = target - now;
            if (diff <= 0) {
                ['ilmxN9Hours','ilmxN9Minutes','ilmxN9Seconds'].forEach(function(id){document.getElementById(id).textContent='00';});
                if(todayEl) todayEl.innerHTML='🌙 <strong>Sudah masuk waktu berbuka! Selamat berbuka puasa!</strong>';
                clearInterval(countdownInterval); return;
            }
            document.getElementById('ilmxN9Hours').textContent=String(Math.floor(diff/3600000)).padStart(2,'0');
            document.getElementById('ilmxN9Minutes').textContent=String(Math.floor((diff%3600000)/60000)).padStart(2,'0');
            document.getElementById('ilmxN9Seconds').textContent=String(Math.floor((diff%60000)/1000)).padStart(2,'0');
        }, 1000);
    }

    document.addEventListener('DOMContentLoaded', function() {
        var btns = document.querySelectorAll('.ilmx-n9-zone-btn');
        btns.forEach(function(btn) {
            btn.addEventListener('click', function() {
                btns.forEach(function(b){b.classList.remove('active');});
                btn.classList.add('active');
                currentZone = parseInt(btn.dataset.zone);
                renderTable();
                updateCards();
                startCountdown();
            });
        });
        renderTable();
        updateCards();
        startCountdown();
    });

